const $=id=>document.getElementById(id),labels=['Not assessed','Needs support','Developing','Confident'],shortNames={E1:'Entry 1',E3:'Entry 3',L1:'Level 1',L2:'Level 2'};
const key='learning-grid-preview-v1';
function seed(){let ratings={};Object.entries(LEVELS).forEach(([l,d],li)=>{ratings[l]=d.topics.map((_,r)=>NAMES.map((_,p)=>r>10?0:((r*11+p*7+li)%10<3?0:((r+p*2+li)%3+1))));});return {names:[...NAMES],ratings,date:new Date().toLocaleDateString('en-CA'),level:'E1'};}
let state;try{state=JSON.parse(localStorage.getItem(key))}catch{}if(!state?.ratings||state.names?.length!==12)state=seed();let mode='compact',history=[],selection=null;
const esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').style.display='none',3500)}
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('saved').textContent='✓ Saved on this device'}catch{$('saved').textContent='Storage unavailable — export to keep changes'} }
function dot(s){return `<i class="dot s${s}"></i>`}
function recordTable(indices,people,interactive=true){let d=LEVELS[state.level];return `<thead><tr><th class="topic-head" rowspan="2">Topic / reference</th>${people.map(p=>`<th colspan="3" class="group">${esc(state.names[p])}</th>`).join('')}</tr><tr>${people.map(()=>['Red','Amber','Green'].map((x,j)=>`<th class="rag r${j+1}">${x}</th>`).join('')).join('')}</tr></thead><tbody>${indices.map(r=>`<tr><td class="topic">${esc(d.topics[r][1])}<small>${esc(d.topics[r][0])}</small></td>${people.map(p=>[1,2,3].map(s=>`<td>${interactive?`<button class="cellbtn tick" data-r="${r}" data-p="${p}" data-s="${s}" aria-label="${esc(state.names[p])}: ${esc(d.topics[r][1])}, ${labels[s]}" aria-pressed="${state.ratings[state.level][r][p]===s}">`:''}${state.ratings[state.level][r][p]===s?'✓':''}${interactive?'</button>':''}</td>`).join('')).join('')}</tr>`).join('')}</tbody>`}
function render(){let l=state.level,d=LEVELS[l],indices=d.topics.map((_,i)=>i).filter(i=>d.topics[i].join(' ').toLowerCase().includes($('search').value.toLowerCase()));$('levelnav').innerHTML=Object.keys(LEVELS).map(k=>`<button class="level ${l===k?'active':''}" data-level="${k}"><b>${k}</b>${shortNames[k]}<small>${LEVELS[k].topics.length}</small></button>`).join('');$('levelTitle').textContent=shortNames[l]+' assessments';$('subheading').textContent='Maths · Self-assessment · Sample group';$('topicCount').textContent=d.topics.length;let total=d.topics.length*12,recorded=state.ratings[l].flat().filter(Boolean).length;$('rated').textContent=Math.round(recorded/total*100)+'%';$('progressText').textContent=`${recorded} of ${total} recorded`;$('progressFill').style.width=recorded/total*100+'%';$('rowCount').textContent=`${indices.length} of ${d.topics.length} topics · 12 learners`;$('date').value=state.date;$('undo').disabled=!history.length;$('compactBtn').classList.toggle('selected',mode==='compact');$('recordBtn').classList.toggle('selected',mode==='record');$('grid').className=mode==='record'?'official':'';$('grid').style.minWidth=mode==='record'?'1850px':'';
$('grid').innerHTML=mode==='record'?recordTable(indices,state.names.map((_,i)=>i)):`<thead><tr><th class="topic-head">Learning topic</th>${state.names.map(n=>`<th class="person"><span>${esc(n)}</span></th>`).join('')}</tr></thead><tbody>${indices.map(r=>`<tr><td class="topic">${esc(d.topics[r][1])}<small>${esc(d.topics[r][0])}</small></td>${state.names.map((n,p)=>`<td><button class="cellbtn" data-r="${r}" data-p="${p}" aria-label="${esc(n)}: ${esc(d.topics[r][1])}, ${labels[state.ratings[l][r][p]]}">${dot(state.ratings[l][r][p])}</button></td>`).join('')}</tr>`).join('')}</tbody>`;
if(!indices.length)$('grid').innerHTML='<tbody><tr><td style="height:180px">No topics match. Try a different search.</td></tr></tbody>';}
function update(r,p,value){let l=state.level;history.push({l,r,p,old:state.ratings[l][r][p]});state.ratings[l][r][p]=value;save();render();}
$('grid').onclick=e=>{let b=e.target.closest('[data-r]');if(!b)return;let r=+b.dataset.r,p=+b.dataset.p;if(b.dataset.s){let s=+b.dataset.s;update(r,p,state.ratings[state.level][r][p]===s?0:s);return;}selection={r,p};$('pickName').textContent=state.names[p];$('pickTopic').textContent=LEVELS[state.level].topics[r][1];$('choices').innerHTML=[1,2,3,0].map(s=>`<button data-choice="${s}" class="${state.ratings[state.level][r][p]===s?'current':''}">${dot(s)}${labels[s]}</button>`).join('');$('picker').showModal();};
$('choices').onclick=e=>{let b=e.target.closest('[data-choice]');if(b){update(selection.r,selection.p,+b.dataset.choice);$('picker').close();}};
$('levelnav').onclick=e=>{let b=e.target.closest('[data-level]');if(b){state.level=b.dataset.level;$('search').value='';save();render();}};
$('search').oninput=render;$('compactBtn').onclick=()=>{mode='compact';render()};$('recordBtn').onclick=()=>{mode='record';render()};$('gridNav').onclick=()=>{$('tableWrap').scrollIntoView({behavior:'smooth'})};
$('undo').onclick=()=>{let h=history.pop();if(h){state.ratings[h.l][h.r][h.p]=h.old;state.level=h.l;save();render();toast('Last assessment change undone')}};
$('date').onchange=()=>{state.date=$('date').value;save()};$('reset').onclick=()=>{if(confirm('Replace your changes with the fictional sample data?')){state=seed();history=[];save();render();toast('Sample data restored')}};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('learnersNav').onclick=()=>{$('nameFields').innerHTML=state.names.map((n,i)=>`<input name="learner${i}" value="${esc(n)}" maxlength="60" required aria-label="Learner ${i+1}">`).join('');$('learnersDialog').showModal()};$('learnerForm').onsubmit=e=>{e.preventDefault();let names=[...$('nameFields').querySelectorAll('input')].map(x=>x.value.trim());if(names.some(x=>!x)){toast('Please enter a name for every learner');return;}state.names=names;save();render();$('learnersDialog').close();toast('Learner names updated')};
function showExport(){$('paperTitle').textContent=LEVELS[state.level].title;$('paperMeta').textContent='Assessment date: '+state.date+' · Learners 1–3';$('paperTable').innerHTML='<table class="official">'+recordTable([0,1,2,3,4],[0,1,2],false)+'</table>';$('exportDialog').showModal()}
$('previewBtn').onclick=showExport;$('exportBtn').onclick=showExport;
async function exportWorkbook(){let button=$('downloadBtn');button.disabled=true;button.textContent='Preparing workbook…';try{let l=state.level,response=await fetch(l+'-template.xlsx');if(!response.ok)throw Error('Template unavailable');let zip=await JSZip.loadAsync(await response.arrayBuffer());for(const path of Object.keys(zip.files).filter(p=>p.endsWith('.xml'))){let xml=await zip.file(path).async('string');xml=xml.replace(/\{\{META\}\}/g,esc('Assessment date: '+state.date+' | Template v1 | Sample group')).replace(/\{\{NAME_(\d+)\}\}/g,(_,p)=>esc(state.names[+p])).replace(/\{\{T_(\d+)_(\d+)_(\d+)\}\}/g,(_,r,p,s)=>state.ratings[l][+r][+p]===+s?'✓':'');zip.file(path,xml);}let blob=await zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=l+'-Self-assessment-'+state.date+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),15000);toast('Excel downloaded · all topics and 12 learners included');}catch(e){toast('Export failed. Please try again.');console.error(e)}finally{button.disabled=false;button.textContent='↓ Download Excel'}}
$('downloadBtn').onclick=exportWorkbook;render();
